steps.command:
cat > /srv/queue/drain.pl <<'PERLEOF'
use strict; use warnings;
use IO::Handle;
my $JOBS = "/srv/queue/jobs.txt";
my @pids;
for my $i (0..2) {
    my $pid = fork(); die "fork: $!" unless defined $pid;
    if (!$pid) {
        my $stop = 0;
        $SIG{INT} = sub { $stop = 1 };
        open(my $out, '>>', "/srv/queue/done-$i.log") or die $!;
        $out->autoflush(1);
        open(my $jf, '<', $JOBS) or die $!; my @jobs = <$jf>; close $jf;
        for my $j (@jobs) {
            chomp $j;
            if ($stop) { print $out "drained before $j\n"; last }
            print $out "processed $j\n";
            select(undef, undef, undef, 0.2);
        }
        print $out "worker $i exit\n";
        close $out;
        exit 0;
    }
    push @pids, $pid;
}
select(undef, undef, undef, 0.7);
kill 'INT', $_ for @pids;
waitpid($_, 0) for @pids;
print "all workers drained\n";
PERLEOF
perl -c /srv/queue/drain.pl
